# ============ 校验 & 输出 ============
def add_id(lst, prefix):
    typ={'s':'single','m':'multi','j':'judge'}[prefix]
    out=[]
    for i,q in enumerate(lst,1):
        q=dict(q); q["id"]="%s%03d"%(prefix,i); q["type"]=typ
        # 校验 answer 合法
        assert 0 < len(q["answer"]) <= len(q["options"]), "选项下标越界或为空: "+q["id"]
        assert all(0<=a<len(q["options"]) for a in q["answer"]), "选项下标越界: "+q["id"]
        assert len(set(q["answer"]))==len(q["answer"]), "answer 重复: "+q["id"]
        # 判断/单选须恰好 1 个答案；多选≥2
        if typ in ('single','judge'):
            assert len(q["answer"])==1, "单选/判断应只有1个答案: "+q["id"]
        else:
            assert len(q["answer"])>=2, "多选应≥2个答案: "+q["id"]
        out.append(q)
    return out

data={"single":add_id(single,"s"),"multi":add_id(multi,"m"),"judge":add_id(judge,"j")}
# 校验 id 唯一
allids=[q["id"] for k in data for q in data[k]]
assert len(allids)==len(set(allids)), "id 重复!"
with open("quiz_data.json","w",encoding="utf-8") as f:
    json.dump(data,f,ensure_ascii=False,indent=1)
print("OK: single=%d multi=%d judge=%d 总=%d"%(len(data["single"]),len(data["multi"]),len(data["judge"]),len(single)+len(multi)+len(judge)))
